# ---- RR12 R028 composed layer: BMR + DENS + DENS-PAIR
# + RW-ADD (NEW LAW host: CTRL12N ballot) ----
BMR_DIST_MIN = 30.0  # frozen at slate: DISC q75 of
# the CTRL12N host book's losing-pick distances (pips)
DENS_DIST_MIN = 30.0  # frozen at slate: DISC q90
PAIR_LO = 20.0  # DENS-PAIR class: SL-hit losses with
PAIR_HI = 25.0  # distance in [PAIR_LO, PAIR_HI)


def _iso_week3(ts):
    return _dt.datetime.utcfromtimestamp(
        int(ts)).isocalendar()[:2]


def _pair_loss(pick):
    """DENS-PAIR class membership: an SL-hit loss (net
    exactly -dist - 2.5) whose distance sits in the
    frozen pair-forming band."""
    if pick["net"] is None or float(pick["net"]) > 0:
        return False
    d = float(pick["dist"])
    return (PAIR_LO <= d < PAIR_HI
            and abs(float(pick["net"]) + d + 2.5) < 1e-6)


class AprStackNFillState:
    """The RR12 R028 ASTACK-N book: the CTRL12N ballot
    fill (87m three-book ballot + protection clause at
    the NEW-LAW walk, TP = 2 x SL) settled by the inner
    FillState, composed with a recorded-pick layer. At
    each slot the inner ballot records at most ONE main
    pick, priced under its source book b* (the pick's
    own src); every composed-layer row at the slot is
    priced under b*: (a) BMR -- when the recorded main
    pick is a loss AND either its SL distance >=
    BMR_DIST_MIN (BRA arm) or it extends this composed
    MAIN stream's consecutive-loss run to >= 2 (BLK
    arm, any distance), the recorded pick is replaced
    by the best same-slot alternative row (B[b*]
    in-band, net > 0, strictly smaller distance,
    different symbol, not recorded at the slot,
    unblocked in this composed book's ledger);
    (b) DENS -- a BRA-qualifying loss at distance >=
    DENS_DIST_MIN with NO alternative row is dropped;
    (c) DENS-PAIR -- a surviving main pick that is a
    class loss (SL hit, distance in [PAIR_LO, PAIR_HI))
    is dropped when the trailing-10 recorded picks
    already hold a class loss (one class loss per
    trailing-10 window; conversions keep priority --
    the ceiling reads the post-BMR survivor only);
    (d) RW-ADD -- after the slot's main pick is
    recorded, if this book's running net in the slot's
    ISO week is < 0, one second pick is added at the
    same slot (best row priced under b*, net > 0,
    unblocked, not already recorded at the slot). The
    replacement trigger and loss-run state read the
    composed MAIN stream only and are decided per pick
    in slot order before the slot's add, so the adds
    layer cannot clear the trigger. A dropped slot
    records nothing and gets no add. Only recorded
    picks change; the inner book settles its own
    ledger first. Drive convention (April,
    verify_module48 form): a FRESH AprStackNFillState
    per era. The surgical log (self.surg) records every
    replacement / drop / add with the original or
    dropped pick, for the pick-log DSR family."""

    def __init__(self):
        self.inner = FillState()
        self.ev = self.inner.ev
        self.picks = []
        self.rec_exit = {}
        self.run_net = {}
        self.main_run = 0
        self.census = {"bmr_bra": 0, "bmr_blk": 0,
                       "bmr_replace": 0, "bmr_no_alt": 0,
                       "dens_drop": 0, "pair_drop": 0,
                       "adds": 0}
        self.surg = []

    # -- persistence (candidate _Form + drive) --
    def to_dict(self):
        return {"inner": self.inner.to_dict(),
                "picks": self.picks,
                "rec_exit": {k: ("inf" if v == float("inf")
                                 else int(v))
                             for k, v in
                             self.rec_exit.items()},
                "run_net": {f"{k[0]}-{k[1]}": v
                            for k, v in
                            self.run_net.items()},
                "main_run": self.main_run,
                "census": self.census,
                "surg": self.surg}

    def from_dict(self, d):
        self.inner.from_dict(d.get("inner", {}))
        self.ev = self.inner.ev
        self.picks = d.get("picks", [])
        self.rec_exit = {k: (float("inf") if v == "inf"
                             else int(v))
                         for k, v in d.get("rec_exit",
                                           {}).items()}
        self.run_net = {}
        for k, v in d.get("run_net", {}).items():
            y, w = k.split("-")
            self.run_net[(int(y), int(w))] = v
        self.main_run = d.get("main_run", 0)
        self.census = d.get("census", self.census)
        self.surg = d.get("surg", [])

    def resolve_pending(self, m15_bars):
        self.inner.resolve_pending(m15_bars)
        for pick in self.picks:
            if pick["exit"] is not None:
                continue
            bars = m15_bars.get(pick["sym"])
            if bars is None:
                continue
            xp, net = _trade_outcome(
                bars, pick["sym"], pick["entry_s"],
                pick["side"], pick["dist"])
            if xp is None:
                continue
            pick["exit"] = int(xp)
            pick["net"] = float(net)
        self.rec_exit = {}
        for p in self.picks:
            ex = p["exit"] if p["exit"] is not None                 else float("inf")
            self.rec_exit[p["sym"]] = max(
                self.rec_exit.get(p["sym"], -1), ex)

    # -- composed bookkeeping --
    def _unblocked(self, sym, T):
        return self.rec_exit.get(sym, -1) <= T

    def _best(self, rows, T, b, dist_max, skip_syms):
        cand = []
        for r in rows:
            per = r["B"][b]
            if not per["in_band"]:
                continue
            if per["net"] is None or float(per["net"]) <= 0:
                continue
            if not float(per["dist"]) < dist_max:
                continue
            if r["sym"] in skip_syms:
                continue
            if not self._unblocked(r["sym"], T):
                continue
            cand.append(r)
        if not cand:
            return None
        return min(cand, key=lambda r: (
            -float(r["B"][b]["score"]),
            float(r["B"][b]["dist"]),
            SYM_IDX[r["sym"]],
            0 if r["side"] > 0 else 1))

    def _record(self, row, T, b, source):
        per = row["B"][b]
        pick = {"sym": row["sym"], "entry_s": int(T),
                "side": int(row["side"]),
                "dist": float(per["dist"]),
                "entry_px": float(row["entry_px"]),
                "score": float(per["score"]),
                "tier": PRIORITY.index(b) + 1,
                "src": b, "layer": "bmr_stack",
                "refused": False,
                "exit": per["exit"], "net": per["net"],
                "source": source}
        self.picks.append(pick)
        if per["exit"] is None:
            self.rec_exit[row["sym"]] = float("inf")
        else:
            self.rec_exit[row["sym"]] = max(
                self.rec_exit.get(row["sym"], -1),
                int(per["exit"]))
        wk = _iso_week3(T)
        self.run_net[wk] = self.run_net.get(wk, 0.0)             + float(per["net"] or 0.0)
        return pick

    def process_slot(self, ts, era, rows):
        made_in = self.inner.process_slot(ts, era, rows)
        if not made_in:
            return []
        main_pick = self.inner.picks[-1]
        b = main_pick["src"]
        made = []
        dropped = False
        rec = None
        if main_pick["net"] is not None                 and float(main_pick["net"]) <= 0:
            d = float(main_pick["dist"])
            bra = d >= BMR_DIST_MIN
            blk = self.main_run >= 1
            if bra or blk:
                if bra:
                    self.census["bmr_bra"] += 1
                if blk:
                    self.census["bmr_blk"] += 1
                alt = self._best(rows, ts, b, d,
                                 {main_pick["sym"]})
                if alt is not None:
                    rec = self._record(alt, ts, b, "BMR")
                    self.census["bmr_replace"] += 1
                    self.surg.append({
                        "kind": "replace",
                        "entry_s": int(ts),
                        "rec_idx": len(self.picks) - 1,
                        "rec": dict(rec),
                        "orig": dict(main_pick),
                        "dropped": None})
                else:
                    self.census["bmr_no_alt"] += 1
                    if bra and d >= DENS_DIST_MIN:
                        dropped = True
                        self.census["dens_drop"] += 1
                        dp = dict(main_pick)
                        dp["source"] = "CTRL"
                        self.surg.append({
                            "kind": "dens_drop",
                            "entry_s": int(ts),
                            "rec_idx": None, "rec": None,
                            "orig": None, "dropped": dp})
        if dropped:
            return made
        if rec is None and _pair_loss(main_pick):
            tail = self.picks[-10:]
            if sum(1 for p in tail if _pair_loss(p)) >= 1:
                dp = dict(main_pick)
                dp["source"] = "CTRL"
                self.surg.append({
                    "kind": "pair_drop",
                    "entry_s": int(ts),
                    "rec_idx": None, "rec": None,
                    "orig": None, "dropped": dp})
                self.census["pair_drop"] += 1
                return made
        if rec is None:
            rec = dict(main_pick)
            rec["source"] = "CTRL"
            self.picks.append(rec)
            if rec["exit"] is None:
                self.rec_exit[rec["sym"]] = float("inf")
            else:
                self.rec_exit[rec["sym"]] = max(
                    self.rec_exit.get(rec["sym"], -1),
                    int(rec["exit"]))
            wk = _iso_week3(ts)
            self.run_net[wk] = self.run_net.get(wk, 0.0)                 + float(rec["net"] or 0.0)
        if float(rec["net"] or 0.0) <= 0:
            self.main_run += 1
        else:
            self.main_run = 0
        made.append(rec)
        wk = _iso_week3(ts)
        if self.run_net.get(wk, 0.0) < 0:
            add = self._best(rows, ts, b, float("inf"),
                             {p["sym"] for p in made})
            if add is not None:
                rec2 = self._record(add, ts, b, "RWADD")
                self.census["adds"] += 1
                self.surg.append({
                    "kind": "add", "entry_s": int(ts),
                    "rec_idx": len(self.picks) - 1,
                    "rec": dict(rec2), "orig": None,
                    "dropped": None})
                made.append(rec2)
        return made
